frame.store("leans_on_a_subject", { let __signature_2821 = Signature { name: "leans_on_a_subject".into(), positional: vec!["understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_2823 = Value::dict(); __attrs_2823.dict_set(Value::from("__doc__"), Value::from("True when the line leans on the subject before it, rather than saying something itself.\n\n    A question left out its subject on purpose (\"how long in the oven?\"), and a line that\n    points back at the thing (\"is that bad\", \"its 3 years old\") is about it. A statement that\n    names its own subject is not: \"i have a cat\" then \"i work nights\" was answered with the\n    cats-at-night entry, because the carried subject was searched together with the line's own\n    words - \"cat\" plus \"nights\" reached an entry neither of them was about, and the person had\n    only said what their job was. Nothing else about the night shift was ever said, so the reply\n    answered a subject they had not raised.\n    "))?; __attrs_2823.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_2824 = Value::dict(); __attrs_2823.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_2820 = Frame::module(frame.globals.clone()); let mut __function_2822 = NativeFunction::qualified_with_origin("leans_on_a_subject".into(), "leans_on_a_subject".into(), "bot.knowledge.lookup".into(), __attrs_2823, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/lookup.py", first: 6294, last: 6312, qualname: "leans_on_a_subject" }, closure: __closure_2820.clone(), freevars: vec![] }, move |rt, args| __py_180::leans_on_a_subject(rt, __closure_2820.clone(), &__signature_2821, args)); __function_2822 })?;
