frame.store("_plainer", { let __default_2900 = frame.load(rt, "PLAIN_MARGIN")?; let __signature_2898 = Signature { name: "_plainer".into(), positional: vec!["plain".into(),"framed".into(),"margin".into()], positional_only: 0, defaults: vec![__default_2900], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_2901 = Value::dict(); __attrs_2901.dict_set(Value::from("__doc__"), Value::from("True when the whole line reaches a clearly better entry than the line without its clause.\n\n    A margin, not a straight comparison: reading the left-out thing as the subject beats the\n    rest of the line by one rank point in plenty of lines where it is wrong (\"how do i stop my\n    baby crying without picking him up\" reaches the skin-picking entry that way), and the entry\n    that wins here has to win by more than that to be believed.\n    "))?; __attrs_2901.dict_set(Value::from("__defaults__"), Value::tuple(__signature_2898.defaults.clone()))?; let __kwdefaults_2902 = Value::dict(); __attrs_2901.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_2897 = Frame::module(frame.globals.clone()); let mut __function_2899 = NativeFunction::qualified_with_origin("_plainer".into(), "_plainer".into(), "bot.knowledge.lookup".into(), __attrs_2901, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/lookup.py", first: 6582, last: 6592, qualname: "_plainer" }, closure: __closure_2897.clone(), freevars: vec![] }, move |rt, args| __py_189::_plainer(rt, __closure_2897.clone(), &__signature_2898, args)); __function_2899 })?;
